class Classifieur(torch.nn.Module):
    def __init__(self):
        super().__init__()
        self.couches = torch.nn.ModuleList([
            torch.nn.Linear(3, 4),
            torch.nn.Linear(4, 2),
        ])
        self.register_buffer("moyenne", torch.zeros(3))

    def forward(self, x):
        h = torch.relu(self.couches[0](x - self.moyenne))
        return self.couches[1](h)
